$_MODULE['<{layerslider}prestashop>_be0233bf54a7d9579cbf0356bce96b17'] = 'Relative URLs verwenden'; // Use relative URLs
$_MODULE['<{layerslider}prestashop>_ba82cbe6dc7a81f3d77fabb6d414c0ee'] = 'Verwenden Sie relative URLs für lokale Bilder. Diese Einstellung kann wichtig sein, wenn Sie Ihre PS-Installation verschieben.'; // Use relative URLs for local images. This setting could be important when moving your PS installation.
$_MODULE['<{layerslider}prestashop>_c878cdf0cb53e7dbeb791eab13b84146'] = 'Neustart der Folien bei Größenänderung erlauben'; // Allow restarting slides on resize
$_MODULE['<{layerslider}prestashop>_0296ddaa31acdc8e379a3de8412aff9a'] = 'Bestimmte Transformations- und Übergangsoptionen können nicht sofort aktualisiert werden, wenn sich die Browsergröße oder die Geräteausrichtung ändert. Durch Aktivieren dieser Option erkennt der Slider solche Situationen automatisch und startet sich neu, um sein Aussehen zu bewahren.'; // Certain transformation and transition options cannot be updated on the fly when the browser size or device orientation changes. By enabling this option, the slider will automatically detect such situations and will restart the itself to preserve its appearance.
$_MODULE['<{layerslider}prestashop>_d9f1451d7e147a9d76732b903c85fd98'] = 'srcset-Attribut verwenden'; // Use srcset attribute
$_MODULE['<{layerslider}prestashop>_d962a6678a6f57c0697bdba39433e0d7'] = 'Das srcset-Attribut ermöglicht das Laden dynamisch skalierter Bilder basierend auf der Bildschirmauflösung. Es kann Bandbreite sparen und die Verwendung von Retina-fähigen Bildern auf hochauflösenden Geräten ermöglichen. In einigen seltenen Grenzfällen kann diese Option zu unscharfen Bildern führen.'; // The srcset attribute allows loading dynamically scaled images based on screen resolution. It can save bandwidth and allow using retina-ready images on high resolution devices. In some rare edge cases, this option might cause blurry images.
$_MODULE['<{layerslider}prestashop>_806790e901a729799c42f26b23c5470f'] = 'Verbessertes Lazy Loading'; // Enhanced lazy load
$_MODULE['<{layerslider}prestashop>_bb477d8d7ee0d5561c80c51482d44904'] = 'Das standardmäßige Lazy-Loading-Verhalten ist ein Kompromiss, um maximale Kompatibilität zu gewährleisten und gleichzeitig eine Lösung zu bieten, die in fast allen Fällen ideal funktioniert. Indem das ’src’-Attribut des Bildes unangetastet bleibt, besteht jedoch eine geringe Wahrscheinlichkeit, dass der Browser für den Bruchteil einer Sekunde einige Assets herunterlädt, bevor Creative Slider sie abbricht. Das Aktivieren dieser Option eliminiert jede Möglichkeit, auch nur eine winzige Menge unerwünschten Datenverkehrs zu erzeugen, kann aber auch Probleme bei der Indexierung durch Suchmaschinen und bei anderen Themes/Modulen verursachen.'; // The default lazy loading behavior makes a compromise to ensure maximum compatibility while offering a solution that works ideally in almost all cases. However, by leaving the image ’src’ attribute untouched, there is a slight chance that the browser might start downloading some assets for a split second before Creative Slider cancels them. Enabling this option will eliminate any chance of generating even a minuscule amount of unwanted traffic, but it can also cause issues for search engine indexing and other themes/modules.
$_MODULE['<{layerslider}prestashop>_451af3f11142c7626d839eb7674d3e0a'] = 'Mischmodus bevorzugen'; // Prefer Blend Mode
$_MODULE['<{layerslider}prestashop>_6da524b45307ee7baa37799db0cd4796'] = 'Aktivieren Sie diese Option, um Probleme mit dem Mischmodus bei Folienübergängen zu vermeiden. Aufgrund technischer Einschränkungen werden Ihre Folienübergänge unabhängig von Ihren Einstellungen ebenfalls beschnitten.'; // Enable this option to avoid blend mode issues with slide transitions. Due to technical limitations, this will also clip your slide transitions regardless of your settings.
$_MODULE['<{layerslider}prestashop>_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Aktiviert'; // Enabled
$_MODULE['<{layerslider}prestashop>_5e1575919121f7253b56bb39b99e1042'] = 'IhrLogo'; // YourLogo
$_MODULE['<{layerslider}prestashop>_367a210257e2ea49914c4a695f8abf70'] = 'Ein festes Bild-Layer kann über dem Slider angezeigt werden, das während des gesamten Sliders stillsteht. Kann zur Anzeige von Logos oder Wasserzeichen verwendet werden.'; // A fixed image layer can be shown above the slider that remains still throughout the whole slider. Can be used to display logos or watermarks.
$_MODULE['<{layerslider}prestashop>_77c34b7517dd216292658ee3b420dd1f'] = 'IhrLogo-Stil'; // YourLogo style
$_MODULE['<{layerslider}prestashop>_355a12e47302b7e2627dc90d1c0e79c6'] = 'CSS-Eigenschaften zur Steuerung der Platzierung und des Aussehens des Bildes.'; // CSS properties to control the image placement and appearance.
$_MODULE['<{layerslider}prestashop>_1cfb56506d3621c27196a6aa02a23c39'] = 'IhrLogo-Link'; // YourLogo link
$_MODULE['<{layerslider}prestashop>_7966bee26ee8f49f0c5693a3b25a3461'] = 'Geben Sie eine URL ein, um das IhrLogo-Bild zu verlinken.'; // Enter a URL to link the YourLogo image.
$_MODULE['<{layerslider}prestashop>_5afb14c537c0ed4ed3805e8f9c12ae68'] = 'Link-Ziel'; // Link target
$_MODULE['<{layerslider}prestashop>_61c717e4d8c25d8ea4fe003f88675e74'] = 'Auf derselben Seite öffnen'; // Open on the same page
$_MODULE['<{layerslider}prestashop>_98a0075b23373e991f18c15fb8442d8b'] = 'Auf neuer Seite öffnen'; // Open on new page
$_MODULE['<{layerslider}prestashop>_67c48b3d90f5ae44e816fe1030452fb3'] = 'Im Eltern-Frame öffnen'; // Open in parent frame
$_MODULE['<{layerslider}prestashop>_e106bc3e705b4e24fe60a249e11c6f01'] = 'Im Haupt-Frame öffnen'; // Open in main frame
$_MODULE['<{layerslider}prestashop>_b77006f2d0398fa7e68ef1a893ef850c'] = 'Beitrags-ID'; // Post ID
$_MODULE['<{layerslider}prestashop>_e4d99041f9e5af92b38767d09947600e'] = 'Beitragstitel'; // Post Title
$_MODULE['<{layerslider}prestashop>_b5e6d43af159d5d593ca7c4b6db55491'] = 'Anzahl der Kommentare'; // Number of Comments
$_MODULE['<{layerslider}prestashop>_cf3fb1ff52ea1eed3347ac5401ee7f0c'] = 'Aufsteigend'; // Ascending
$_MODULE['<{layerslider}prestashop>_e3cf5ac19407b1a62c6fccaff675a53b'] = 'Absteigend'; // Descending
$_MODULE['<{layerslider}prestashop>_1a3cb622f5613168ed16ba4ffcfe49fe'] = 'Ein Folienbild festlegen'; // Set a slide image
$_MODULE['<{layerslider}prestashop>_1cf966e0716f7f365751df6e4a86f43f'] = 'Das Folienbild/Hintergrund. Klicken Sie auf das Bild, um den Bildmanager zu öffnen und ein Bild auszuwählen oder hochzuladen.'; // The slide image/background. Click on the image to open the Image Manager to choose or upload an image.
$_MODULE['<{layerslider}prestashop>_6f6cb72d544962fa333e2e34ce64f719'] = 'Größe'; // Size
$_MODULE['<{layerslider}prestashop>_13eac5a039bc8041315fe1165a245a98'] = 'Die Größe des Folienhintergrundbildes. Lassen Sie diese Option auf "erben", wenn Sie sie global in den Slider-Einstellungen festlegen möchten.'; // The size of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_c49484faf79e2388b580e49444d6ac11'] = 'Erben'; // Inherit
$_MODULE['<{layerslider}prestashop>_52f5e0bc3859bc5f5e25130b6c7e8881'] = 'Position'; // Position
$_MODULE['<{layerslider}prestashop>_25824be059f35ecadb2d38a895f7e710'] = 'Die Position des Folienhintergrundbildes. Lassen Sie diese Option auf "erben", wenn Sie sie global in den Slider-Einstellungen festlegen möchten.'; // The position of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_cb5feb1b7314637725a2e73bdc9f7295'] = 'Farbe'; // Color
$_MODULE['<{layerslider}prestashop>_9880a2532d7550cb4bef6c24ce2275f3'] = 'Die Hintergrundfarbe der Folie. Sie können Farbnamen, hexadezimale, RGB- oder RGBA-Werte verwenden.'; // The slide background color. You can use color names, hexadecimal, RGB or RGBA values.
$_MODULE['<{layerslider}prestashop>_9d8cfafeba857023956c26437b6570fc'] = 'Eine Folien-Miniaturansicht festlegen'; // Set a slide thumbnail
$_MODULE['<{layerslider}prestashop>_b95232d8c69a9f62cd6dab61887acf0f'] = 'Das Miniaturbild dieser Folie. Klicken Sie auf das Bild, um den Bildmanager zu öffnen und ein Bild auszuwählen oder hochzuladen. Wenn Sie dieses Feld leer lassen, wird das Folienbild verwendet.'; // The thumbnail image of this slide. Click on the image to open the Image Manager to choose or upload an image. If you leave this field empty, the slide image will be used.
$_MODULE['<{layerslider}prestashop>_e02d2ae03de9d493df2b6b2d2813d302'] = 'Dauer'; // Duration
$_MODULE['<{layerslider}prestashop>_b0c71ca949422ff07096787e513bf3dc'] = 'Hier können Sie das Zeitintervall zwischen den Folienwechseln festlegen, diese Folie bleibt für die hier angegebene Zeit sichtbar. Dieser Wert ist in Millisekunden, also bedeutet der Wert 1000 1 Sekunde. Bitte verwenden Sie keine 0 oder sehr niedrige Werte.'; // Here you can set the time interval between slide changes, this slide will stay visible for the time specified here. This value is in millisecs, so the value 1000 means 1 second. Please don't use 0 or very low values.
$_MODULE['<{layerslider}prestashop>_4357cfb0b7acc1db400c94094794ae17'] = 'Wir haben unsere vordefinierten Folienübergänge mit besonderer Sorgfalt erstellt, um in die meisten Anwendungsfälle zu passen. Wenn Sie jedoch die Geschwindigkeit dieser Übergänge erhöhen oder verringern möchten, können Sie deren Timing hier überschreiben, indem Sie Ihre eigene Übergangsdauer in Millisekunden angeben. (1 Sekunde = 1000 Millisekunden)'; // We've made our pre-defined slide transitions with special care to fit in most use cases. However, if you would like to increase or decrease the speed of these transitions, you can override their timing here by providing your own transition length in milliseconds. (1 second = 1000 milliseconds)
$_MODULE['<{layerslider}prestashop>_38912a644194123a9ee9d01e126fcfae'] = 'benutzerdefinierte Dauer'; // custom duration
$_MODULE['<{layerslider}prestashop>_1605a4f4a4e45503d3ac914de9fba80a'] = 'Zeitverschiebung'; // Time Shift
$_MODULE['<{layerslider}prestashop>_6d106138f5fadb601a337fca4d4b7a2e'] = 'Sie können den Startpunkt der Folienanimations-Zeitleiste verschieben, sodass Layer nach einem Folienwechsel früher animiert werden können. Dieser Wert ist in Millisekunden. Eine Sekunde entspricht 1000 Millisekunden. Sie können nur einen negativen Wert verwenden.'; // You can shift the starting point of the slide animation timeline, so layers can animate in an earlier time after a slide change. This value is in milliseconds. A second is 1000 milliseconds. You can only use a negative value.
$_MODULE['<{layerslider}prestashop>_e1f70f4a4265cb51c1b219aa60eaa441'] = 'URL eingeben'; // Enter URL
$_MODULE['<{layerslider}prestashop>_cfdb83fef5ccd56abb3592f98391b355'] = 'Wenn Sie die gesamte Folie verlinken möchten, geben Sie hier die URL ein. Sie können eine der vordefinierten Optionen aus der Dropdown-Liste auswählen, wenn Sie in dieses Feld klicken. Sie können auch ein Rautezeichen gefolgt von einer Zahl eingeben, um diesen Layer mit einer anderen Folie zu verknüpfen. Beispiel: #3 - dies wechselt zur dritten Folie.'; // If you want to link the whole slide, type the URL here. You can choose one of the pre-defined options from the dropdown list when you click into this field. You can also type a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_1f7412ef1f7fdba3cc269af9a0b7a40c'] = 'Link-Ziel'; // Link Target
$_MODULE['<{layerslider}prestashop>_e82688575274fd1ba522f5044431cc93'] = 'Zum Element scrollen (Selektor eingeben)'; // Scroll to element (Enter selector)
$_MODULE['<{layerslider}prestashop>_1fc71d8275be86e2787bc4a8f0d62c84'] = 'Wählen Sie, ob der Folienlink über oder unter Ihren Layern liegen soll. Letztere Option macht den Link nur in leeren Bereichen klickbar, in denen der Folienhintergrund sichtbar ist, und ermöglicht es Ihnen, sowohl Folien als auch Layer unabhängig voneinander zu verlinken.'; // Choose whether the slide link should be on top or underneath your layers. The later option makes the link clickable only at empty spaces where the slide background is visible, and enables you to link both slides and layers independently from each other.
$_MODULE['<{layerslider}prestashop>_7e04fe64ab136e31d62fcc6ea113f1ca'] = 'Über den Layern'; // On top of layers
$_MODULE['<{layerslider}prestashop>_d722a275a3f48eb46d892c9df863e1af'] = 'Unter den Layern'; // Underneath layers
$_MODULE['<{layerslider}prestashop>_739cea2b85156183f917f2ccaa10a50c'] = '#ID'; // #ID
$_MODULE['<{layerslider}prestashop>_06f695600f91bfbd579d9d8f5a0147bd'] = 'Sie können dem HTML-Element dieser Folie ein ID-Attribut zuweisen, um damit in Ihrem benutzerdefinierten CSS- oder Javascript-Code zu arbeiten.'; // You can apply an ID attribute on the HTML element of this slide to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_550dc007dba485adc22eddfe0af40a81'] = 'Deeplink'; // Deeplink
$_MODULE['<{layerslider}prestashop>_070cb374111546db9ae4642406963ebd'] = 'Sie können einen Folien-Alias-Namen angeben, den Sie in Ihren URLs mit einem Rautezeichen verwenden können, sodass Creative Slider mit der entsprechenden Folie startet.'; // You can specify a slide alias name which you can use in your URLs with a hash mark, so Creative Slider will start with the correspondig slide.
$_MODULE['<{layerslider}prestashop>_436e4906cf91bb911a38eb161e858a69'] = 'Globales Hover'; // Global Hover
$_MODULE['<{layerslider}prestashop>_f22bc2f96ed30d26a29060598c44c2fa'] = 'Wenn Sie diese Option aktivieren, lösen alle Layer ihre Hover-Übergänge gleichzeitig aus, wenn Sie mit dem Mauszeiger über den Slider fahren. Dies ist nützlich, um spektakuläre Effekte zu erstellen, die mehrere Layer-Übergänge beinhalten und beim Überfahren des Sliders anstelle einzelner Layer aktiviert werden.'; // By turning this option on, all layers will trigger their Hover Transitions at the same time when you hover over the slider with your mouse cursor. It’s useful to create spectacular effects that involve multiple layer transitions and activate on hovering over the slider instead of individual layers.
$_MODULE['<{layerslider}prestashop>_7acdf85c69cc3c5305456a293524386e'] = 'Versteckt'; // Hidden
$_MODULE['<{layerslider}prestashop>_a494a9272210a3aa3682f9fa8b6ad9fc'] = 'Wenn Sie diese Folie nicht auf Ihrer Startseite verwenden, aber behalten möchten, können Sie sie mit diesem Schalter ausblenden.'; // If you don't want to use this slide in your front-page, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_d33fd48027b557f5bcb3f15a238d7537'] = 'Überlaufende Layer'; // Overflow layers
$_MODULE['<{layerslider}prestashop>_5bbae9c02b64de11da4d22707a297710'] = 'Standardmäßig beschneidet der Slider die Layer außerhalb seiner Grenzen. Aktivieren Sie diese Option, um überlaufenden Inhalt zu erlauben.'; // By default the slider clips the layers outside of its bounds. Enable this option to allow overflowing content.
$_MODULE['<{layerslider}prestashop>_57ffe7327fb6fb004c59466a978c4100'] = 'Startet am'; // Start on
$_MODULE['<{layerslider}prestashop>_6ba9104be4da1fea318c02faca91dad6'] = 'Die geplante Folie ist für Ihre Besucher nur während des hier festgelegten Zeitraums sichtbar.<br>Wir verwenden das internationale Datums- und Zeitformat, um Unklarheiten zu vermeiden.'; // Scheduled slide will only be visible to your visitors between the time period you set here.<br>We're using international date and time format to avoid ambiguity.
$_MODULE['<{layerslider}prestashop>_6ea6d7b483daeb9be3acaad212b04181'] = 'Stoppt am'; // Stop on
$_MODULE['<{layerslider}prestashop>_b78a3223503896721cca1303f776159b'] = 'Titel'; // Title
$_MODULE['<{layerslider}prestashop>_a2e92861b757ab878312dd57993d60cf'] = 'Alt'; // Alt
$_MODULE['<{layerslider}prestashop>_f17b29e841d3183298a453dc423242a0'] = 'Benennen oder beschreiben Sie Ihr Folienbild, damit Suchmaschinen und VoiceOver-Software es richtig identifizieren können.'; // Name or describe your slide image, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_4252b72e6ebcd4d4b4c2e46a786f03d2'] = 'Zoom'; // Zoom
$_MODULE['<{layerslider}prestashop>_f5ca4abce85e2dddb0342d0bae3a7270'] = 'Vergrößern'; // Zoom In
$_MODULE['<{layerslider}prestashop>_30850b501f98539b1aabaa29fabe41ef'] = 'Verkleinern'; // Zoom Out
$_MODULE['<{layerslider}prestashop>_8d2de5368588552fbae54044ac5c7b3d'] = 'Drehen'; // Rotate
$_MODULE['<{layerslider}prestashop>_8aa2fa2e684ba408f551f3504c47427e'] = 'Der Betrag der Drehung (falls vorhanden) in Grad, der im Ken-Burns-Effekt verwendet wird. Negative Werte sind für eine Drehung gegen den Uhrzeigersinn erlaubt.'; // The amount of rotation (if any) in degrees used in the Ken Burns effect. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_85a7cd587d6142dbfc1a4de05af7b75d'] = 'Skalieren'; // Scale
$_MODULE['<{layerslider}prestashop>_2ed8e1d37be922f23b2713c3e69a85ae'] = 'Erhöhen oder verringern Sie die Größe des Folienhintergrundbildes im Ken-Burns-Effekt. Der Standardwert ist 1, der Wert 2 verdoppelt das Bild, während 0,5 die halbe Größe ergibt. Negative Werte spiegeln das Bild.'; // Increase or decrease the size of the slide background image in the Ken Burns effect. The default value is 1, the value 2 will double the image, while 0.5 results half the size. Negative values will flip the image.
$_MODULE['<{layerslider}prestashop>_a1fa27779242b4902f7ae3bdd5c6d508'] = 'Typ'; // Type
$_MODULE['<{layerslider}prestashop>_4a2d97fd5296d09fea3cbe45d107a7b3'] = 'Der Standardwert für Parallax-Layer auf dieser Folie, den sie erben werden, es sei denn, Sie legen ihn auf den betroffenen Layern anders fest.'; // The default value for parallax layers on this slide, which they will inherit, unless you set it otherwise on the affected layers.
$_MODULE['<{layerslider}prestashop>_8c94134f25efe7680f9743b2774e8e1f'] = '2D'; // 2D
$_MODULE['<{layerslider}prestashop>_76aa96369abbba52e621bfa83da8e64f'] = '3D'; // 3D
$_MODULE['<{layerslider}prestashop>_a4ecfc70574394990cf17bd83df499f7'] = 'Ereignis'; // Event
$_MODULE['<{layerslider}prestashop>_87932092d26d18e63889036bbf70518e'] = 'Sie können den Parallax-Effekt entweder durch Scrollen der Seite oder durch Bewegen des Mauszeigers / Neigen Ihres Mobilgeräts auslösen. Dies ist der Standardwert auf dieser Folie, den Parallax-Layer erben werden, es sei denn, Sie legen ihn direkt auf ihnen anders fest.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_58af070b9f7f3dc090af0ece708e8869'] = 'Cursor oder Neigung'; // Cursor or Tilt
$_MODULE['<{layerslider}prestashop>_61ca8fa7a7c8b4699523bc8773c306d0'] = 'Achsen'; // Axes
$_MODULE['<{layerslider}prestashop>_fc888362a84b5b975136bbca8e1fc5c6'] = 'Wählen Sie, auf welchen Achsen sich Parallax-Layer bewegen sollen. Dies ist der Standardwert auf dieser Folie, den Parallax-Layer erben werden, es sei denn, Sie legen ihn direkt auf ihnen anders fest.'; // Choose on which axes parallax layers should move. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_6adf97f83acf6453d4a6a4b1070f3754'] = 'Keine'; // None
$_MODULE['<{layerslider}prestashop>_2c452204ed58a6f4a3bcda80344b338a'] = 'Beide Achsen'; // Both axes
$_MODULE['<{layerslider}prestashop>_ad09aaae9c9ffe403ffdb2a6568f5a36'] = 'Nur horizontal'; // Horizontal only
$_MODULE['<{layerslider}prestashop>_354908b89248f3dcbab970b32860a331'] = 'Nur vertikal'; // Vertical only
$_MODULE['<{layerslider}prestashop>_8b622b0a6ecf4e0116eaf248876f8700'] = 'Transformationsursprung'; // Transform Origin
$_MODULE['<{layerslider}prestashop>_e5a904ff73268b65730e4fb8b6127bf1'] = 'Legt einen Punkt auf der Leinwand fest, von dem aus Transformationen berechnet werden. Zum Beispiel kann ein Layer um seine Mittelachse oder einen völlig benutzerdefinierten Punkt, wie eine seiner Ecken, rotieren. Die drei Werte repräsentieren die X-, Y- und Z-Achsen im 3D-Raum. Neben den Pixel- und Prozentwerten können Sie auch die folgenden Konstanten verwenden: top, right, bottom, left, center.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center.
$_MODULE['<{layerslider}prestashop>_97289d779de759c4fe3a0ef9d3a4ff3d'] = 'Bewegungsdauer'; // Move duration
$_MODULE['<{layerslider}prestashop>_ef82e470cae5696da7dc47e9a50fa8f7'] = 'Steuert die Geschwindigkeit der Animation von Layern, wenn Sie Ihren Mauszeiger bewegen oder Ihr Mobilgerät neigen. Dies ist der Standardwert auf dieser Folie, den Parallax-Layer erben werden, es sei denn, Sie legen ihn direkt auf ihnen anders fest.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0bdd8970e06688e4a6ad694b8ed7b9f7'] = 'Verlassensdauer'; // Leave duration
$_MODULE['<{layerslider}prestashop>_9aa9b8945ad7ff74e04fb53dbbe3d1f2'] = 'Steuert, wie schnell Ihre Layer zu ihrer ursprünglichen Position zurückkehren, wenn Sie Ihren Mauszeiger aus einem Parallax-Slider bewegen. Dieser Wert ist in Millisekunden. 1 Sekunde = 1000 Millisekunden. Dies ist der Standardwert auf dieser Folie, den Parallax-Layer erben werden, es sei denn, Sie legen ihn direkt auf ihnen anders fest.'; // Controls how quickly your layers revert to their original position when you move your mouse cursor outside of a parallax slider. This value is in milliseconds. 1 second = 1000 milliseconds. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0aa6f4210bf373c95eda00232e93cd98'] = 'Distanz'; // Distance
$_MODULE['<{layerslider}prestashop>_396950a091a406fcd6f9f4cc75927536'] = 'Erhöhen oder verringern Sie die Bewegungsmenge des Layers, wenn Sie Ihren Mauszeiger bewegen oder auf einem mobilen Gerät neigen. Dies ist der Standardwert auf dieser Folie, den Parallax-Layer erben werden, es sei denn, Sie legen ihn direkt auf ihnen anders fest.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_f1a42bd417390fc63b030a519624607a'] = 'Rotation'; // Rotation
$_MODULE['<{layerslider}prestashop>_331ee65576c7333ba77a13d691219105'] = 'Erhöhen oder verringern Sie die Rotationsmenge des Layers im 3D-Raum, wenn Sie Ihren Mauszeiger bewegen oder auf einem mobilen Gerät neigen. Dies ist der Standardwert auf dieser Folie, den Parallax-Layer erben werden, es sei denn, Sie legen ihn direkt auf ihnen anders fest.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_a80420eef88d11f77532f1b9cb467fa3'] = 'Perspektive'; // Perspective
$_MODULE['<{layerslider}prestashop>_7ba7448042bdf18c7669bec909a0a7be'] = 'Ändert die Perspektive der Layer im 3D-Raum. Dies ist der Standardwert auf dieser Folie, den Parallax-Layer erben werden, es sei denn, Sie legen ihn direkt auf ihnen anders fest.'; // Changes the perspective of layers in the 3D space. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_d6432a4413208eee54d613ceb82f726a'] = 'Filter von'; // Filter From
$_MODULE['<{layerslider}prestashop>_bd3ec381eecf6eb78c9a97594745d33c'] = 'Filter bieten Effekte wie Weichzeichnen oder Farbverschiebung Ihrer Layer. Klicken Sie in das Textfeld, um eine Auswahl von Filtern zu sehen, die Sie verwenden können. Obwohl das Klicken auf die vordefinierten Optionen das Textfeld zurücksetzt, können Sie mehrere Filter anwenden, indem Sie einfach eine durch Leerzeichen getrennte Liste aller Filter angeben, die Sie verwenden möchten.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use.
$_MODULE['<{layerslider}prestashop>_6b770358764a885d6dc7f2be20604356'] = 'Filter bis'; // Filter To
$_MODULE['<{layerslider}prestashop>_05b1dc77590105a18fc4c02526fe0c7a'] = 'Autoplay'; // Autoplay
$_MODULE['<{layerslider}prestashop>_2b3de50de6ab7bd0aaf46ae654032790'] = 'Info anzeigen'; // Show Info
$_MODULE['<{layerslider}prestashop>_24b6472fcfa59cddd3f7bbc326582b5f'] = 'Steuerelemente'; // Controls
$_MODULE['<{layerslider}prestashop>_58bccbc47e6de6783fb90fd62890a171'] = 'Füllmodus'; // Fill mode
$_MODULE['<{layerslider}prestashop>_bd7a9717d29c5ddcab1bc175eda1e298'] = 'Lautstärke'; // Volume
$_MODULE['<{layerslider}prestashop>_56a7f02a3b02e4a16864670ff48745e1'] = 'Dieses Video als Folienhintergrund verwenden'; // Use this video as slide background
$_MODULE['<{layerslider}prestashop>_4ee3787bc7df95d25272524868e60d4d'] = 'Zwingt diesen Layer, wie der Folienhintergrund zu agieren, indem er den gesamten Slider abdeckt und einige Übergänge ignoriert. Bitte stellen Sie sicher, dass Sie Ihr eigenes Posterbild mit der obigen Option bereitstellen, damit der Slider es sofort beim Laden der Seite anzeigen kann.'; // Forces this layer to act like the slide background by covering the whole slider and ignoring some transitions. Please make sure to provide your own poster image with the option above, so the slider can display it immediately on page load.
$_MODULE['<{layerslider}prestashop>_9d16dd63ee0afa947dc998fb3d5a4a96'] = 'Ein Überlagerungsbild auswählen:'; // Choose an overlay image:
$_MODULE['<{layerslider}prestashop>_e13b4cc51565c9030f943e31c253c8aa'] = 'Überlagern Sie Ihre Videos mit einem Überlagerungsbild, um gepunktete oder gestreifte Effekte darauf zu erzielen.'; // Cover your videos with an overlay image to have dotted or striped effects on them.
$_MODULE['<{layerslider}prestashop>_1529fb44e04df26ff7666faa9f58c605'] = 'VersatzX'; // OffsetX
$_MODULE['<{layerslider}prestashop>_0d12fb40782d7877c5018ff4b501e701'] = 'Verschiebt die Startposition des Layers von seiner ursprünglichen auf der horizontalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. Die Werte \'links\' oder \'rechts\' positionieren den Layer außerhalb des Staging-Bereichs, sodass er von beiden Seiten in die Szene eintritt, wenn er zu seinem Zielort animiert wird.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it enters the scene from either side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_1508a7d829d65cf5e117fdc2aca0f155'] = 'VersatzY'; // OffsetY
$_MODULE['<{layerslider}prestashop>_c91f704c049f7d06fe50106d7452c21c'] = 'Verschiebt die Startposition des Layers von seiner ursprünglichen auf der vertikalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Höhe dieses Layers. Die Werte \'oben\' oder \'unten\' positionieren den Layer außerhalb des Staging-Bereichs, sodass er von beiden vertikalen Seiten in die Szene eintritt, wenn er zu seinem Zielort animiert wird.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it enters the scene from either vertical side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_7686cf30c00c9f146a9224a33ba99a0f'] = 'Die Dauer des Übergangs in Millisekunden, wenn der Layer in die Szene eintritt. Eine Sekunde entspricht 1000 Millisekunden.'; // The length of the transition in milliseconds when the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_f2572c86c0aff2b2b7a92fbb6dee1491'] = 'Start bei'; // Start at
$_MODULE['<{layerslider}prestashop>_1f413844a6a15351c7a32a16ce962bfd'] = 'Verzögert den Übergang um die angegebene Anzahl von Millisekunden, bevor der Layer in die Szene eintritt. Eine Sekunde entspricht 1000 Millisekunden.'; // Delays the transition with the given amount of milliseconds before the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_32485d52ad7aea25b3bc80d416e76a3b'] = 'Easing'; // Easing
$_MODULE['<{layerslider}prestashop>_ca9a3cf0ea2e65cd611fe23633cd1186'] = 'Die Timing-Funktion der Animation. Mit dieser Funktion können Sie die Bewegung des animierten Objekts manipulieren. Bitte klicken Sie auf den Link neben diesem Auswahlfeld, um easings.net für weitere Informationen und Echtzeit-Beispiele zu öffnen.'; // The timing function of the animation. With this function you can manipulate the movement of the animated object. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_04e0385c10aefee8e4681617d2f3ef40'] = 'Fade'; // Fade
$_MODULE['<{layerslider}prestashop>_ecdc93d174113fe69b7cbf2c42b5a1cb'] = 'Den Layer während des Übergangs ausblenden.'; // Fade the layer during the transition.
$_MODULE['<{layerslider}prestashop>_b98c4145f7f66383ce71bf31bc4850b2'] = 'Dreht den Layer um die angegebene Gradzahl. Negative Werte sind für eine Drehung gegen den Uhrzeigersinn erlaubt.'; // Rotates the layer by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_801e0dd823542f625e0f2ee135efb62d'] = 'DrehenX'; // RotateX
$_MODULE['<{layerslider}prestashop>_54f64742da0d7bd157ccaf54d4ac73a1'] = 'Dreht den Layer um die X-Achse (horizontal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt.'; // Rotates the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_ea0928ab345567847020e1544892fba0'] = 'DrehenY'; // RotateY
$_MODULE['<{layerslider}prestashop>_209eea8f9d8a60293098e07e8951e156'] = 'Dreht den Layer um die Y-Achse (vertikal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt.'; // Rotates the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_5a013b463ee01be2924568775fdddfb1'] = 'VerzerrenX'; // SkewX
$_MODULE['<{layerslider}prestashop>_253108f96bfad9912bb2178a4c7aef73'] = 'Verzerrt den Layer entlang der X-Achse (horizontal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt.'; // Skews the layer along the X (horizontal) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_eeb66258f8bf4bb3c0763461b5c1797d'] = 'VerzerrenY'; // SkewY
$_MODULE['<{layerslider}prestashop>_9d19b1698a8b2f7b0efa8c91067053dd'] = 'Verzerrt den Layer entlang der Y-Achse (vertikal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt.'; // Skews the layer along the Y (vertical) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_b5e0c179725e7f282ffb8e6a96797b49'] = 'SkalierenX'; // ScaleX
$_MODULE['<{layerslider}prestashop>_15cfa2ea26e51b8489ace013f1b2ec5c'] = 'Skaliert den Layer entlang der X-Achse (horizontal) um den angegebenen Vektor. Verwenden Sie den Wert 1 für die Originalgröße. Der Wert 2 verdoppelt, während 0,5 den Layer im Vergleich zu seiner Originalgröße verkleinert.'; // Scales the layer along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_3475b72c6483a5c871d245e2567c96c7'] = 'SkalierenY'; // ScaleY
$_MODULE['<{layerslider}prestashop>_3db72901337b8e6eeaa04ffd8db52e5e'] = 'Skaliert den Layer entlang der Y-Achse (vertikal) um den angegebenen Vektor. Verwenden Sie den Wert 1 für die Originalgröße. Der Wert 2 verdoppelt, während 0,5 den Layer im Vergleich zu seiner Originalgröße verkleinert.'; // Scales the layer along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_e55d5d854ca64aed330e5591b62ae112'] = 'Legt einen Punkt auf der Leinwand fest, von dem aus Transformationen berechnet werden. Zum Beispiel kann ein Layer um seine Mittelachse oder einen völlig benutzerdefinierten Punkt, wie eine seiner Ecken, rotieren. Die drei Werte repräsentieren die X-, Y- und Z-Achsen im 3D-Raum. Neben den Pixel- und Prozentwerten können Sie auch die folgenden Konstanten verwenden: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.
$_MODULE['<{layerslider}prestashop>_4a18312b5b75f549d5551e5912ad6ebf'] = 'Maske'; // Mask
$_MODULE['<{layerslider}prestashop>_7fb23cb4a33cca7e266b2deda0034711'] = 'Beschneidet die Seiten des Layers um den angegebenen Betrag in Pixeln oder Prozent. Die 4 Werte in der Reihenfolge: oben, rechts, unten und die linke Seite des Layers.'; // Clips (cuts off) the sides of the layer by the given amount specified in pixels or percentages. The 4 value in order: top, right, bottom and the left side of the layer.
$_MODULE['<{layerslider}prestashop>_a9ded1e5ce5d75814730bb4caaf49419'] = 'Hintergrund'; // Background
$_MODULE['<{layerslider}prestashop>_57315a787bf5df775dcdb38f85aacf7b'] = 'Die Hintergrundfarbe Ihres Layers. Sie können Farbnamen, hexadezimale, RGB- oder RGBA-Werte sowie das Schlüsselwort \'transparent\' verwenden. Beispiel: #FFF'; // The background color of your layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_cdb3e9cc0b2932a6d1543d19732761f1'] = 'Die Farbe Ihres Textes. Sie können Farbnamen, hexadezimale, RGB- oder RGBA-Werte verwenden. Beispiel: #333'; // The color of your text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_cabcfc0f365f0e649cf8c229bf54605e'] = 'Abgerundete Ecken'; // Rounded Corners
$_MODULE['<{layerslider}prestashop>_f0d205bfae354c2e65725ed59bc101e7'] = 'Wenn Sie abgerundete Ecken wünschen, können Sie deren Radius hier in Pixeln festlegen. Beispiel: 5px'; // If you want rounded corners, you can set its radius here in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_32954654ac8fe66a1d09be19001de2d4'] = 'Breite'; // Width
$_MODULE['<{layerslider}prestashop>_de11d49b6bbf1b1ecd2b424dc1c0c74a'] = 'Die anfängliche Breite dieses Layers, von der aus er während des Übergangs auf seine richtige Größe animiert wird.'; // The initial width of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_eec6c4bdbd339edf8cbea68becb85244'] = 'Höhe'; // Height
$_MODULE['<{layerslider}prestashop>_4cc10791b724542e8a9a04636995d1f5'] = 'Die anfängliche Höhe dieses Layers, von der aus er während des Übergangs auf seine richtige Größe animiert wird.'; // The initial height of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_d7778d0c64b6ba21494c97f77a66885a'] = 'Filter'; // Filter
$_MODULE['<{layerslider}prestashop>_3f6230752680291a660faeec55dc0b73'] = 'Filter bieten Effekte wie Weichzeichnen oder Farbverschiebung Ihrer Layer. Klicken Sie in das Textfeld, um eine Auswahl von Filtern zu sehen, die Sie verwenden können. Obwohl das Klicken auf die vordefinierten Optionen das Textfeld zurücksetzt, können Sie mehrere Filter anwenden, indem Sie einfach eine durch Leerzeichen getrennte Liste aller Filter angeben, die Sie verwenden möchten. Klicken Sie auf den Link "Filter" für weitere Informationen.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use. Click on the "Filter" link for more information.
$_MODULE['<{layerslider}prestashop>_8cb8ac2653a6471f6779aa5c2d9cded2'] = 'Ändert die Perspektive dieses Layers im 3D-Raum.'; // Changes the perspective of this layer in the 3D space.
$_MODULE['<{layerslider}prestashop>_cb1fa274044590e8c05e0e3fe44dd203'] = 'Verschiebt den Layer von seiner ursprünglichen Position auf der horizontalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. Die Werte \'links\' oder \'rechts\' animieren den Layer aus dem Staging-Bereich, sodass er die Szene von beiden Seiten verlassen kann.'; // Shifts the layer from its original position on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' animate the layer out the staging area, so it can leave the scene on either side.
$_MODULE['<{layerslider}prestashop>_aa243196666cd7d2c5e92dd0f8b9b5f4'] = 'Verschiebt den Layer von seiner ursprünglichen Position auf der vertikalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Höhe dieses Layers. Die Werte \'oben\' oder \'unten\' animieren den Layer aus dem Staging-Bereich, sodass er die Szene von beiden vertikalen Seiten verlassen kann.'; // Shifts the layer from its original position on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' animate the layer out the staging area, so it can leave the scene on either vertical side.
$_MODULE['<{layerslider}prestashop>_f04f3b646758fcab3a12facb6373fdc0'] = 'Die Dauer des Übergangs in Millisekunden, wenn der Layer die Folie verlässt. Eine Sekunde entspricht 1000 Millisekunden.'; // The length of the transition in milliseconds when the layer leaves the slide. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_b92bb5e60806c72def5363a5a8bb035e'] = 'Sie können die Startzeit dieses Übergangs festlegen. Verwenden Sie eine der vordefinierten Optionen, um relatives Timing zu verwenden, das mit benutzerdefinierten Operationen verschoben werden kann.'; // You can set the starting time of this transition. Use one of the pre-defined options to use relative timing, which can be shifted with custom operations.
$_MODULE['<{layerslider}prestashop>_c36ace66cf4777473ba3200cf815253c'] = 'Folienwechsel beginnt (ohne Modifikator)'; // Slide change starts (ignoring modifier)
$_MODULE['<{layerslider}prestashop>_371b285fa971d884eaebf156db4065c8'] = 'Öffnungsübergang abgeschlossen'; // Opening Transition completes
$_MODULE['<{layerslider}prestashop>_8920002666c88ed85ae80665159154f4'] = 'Öffnungstext-Übergang beginnt'; // Opening Text Transition starts
