$_MODULE['<{layerslider}prestashop>_dc08824d508252f7973060a086788ec1'] = 'Öffnungs-, Öffnungstext- und Schleifenübergänge abgeschlossen'; // Opening, Opening Text and Loop Transitions complete
$_MODULE['<{layerslider}prestashop>_1fcb9ccb4471ff55ac855fcb38bd015b'] = 'Endtext-Übergang beginnt'; // Ending Text Transition starts
