$_MODULE['<{layerslider}prestashop>_b24aac7aa06431fba06d552d71c0a5ca'] = 'Endtext- und Schleifenübergänge abgeschlossen'; // Ending Text and Loop Transitions complete
$_MODULE['<{layerslider}prestashop>_7094fc088dddef6adaa665620fe96dcc'] = 'Verzerrt den Layer entlang der X-Achse (horizontal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt.'; // Skews the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_049d4369eb664418bd75569e09641c99'] = 'Verzerrt den Layer entlang der Y-Achse (vertikal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt.'; // Skews the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_e9e245065a77b7927aaccb2cf9d2ffcd'] = 'Wenn Sie diesen Layer nicht verwenden, aber behalten möchten, können Sie ihn mit diesem Schalter ausblenden.'; // If you don't want to use this layer, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_630c4a18856c4ae057355c9398e83a32'] = 'Animiert den Hintergrund zur hier angegebenen Farbe, wenn der Layer die Slider-Leinwand verlässt.'; // Animates the background toward the color you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_77064060d521c47a027e25dab869772f'] = 'Animiert die Textfarbe zur hier angegebenen Farbe, wenn der Layer die Slider-Leinwand verlässt.'; // Animates the text color toward the color you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_f53e87a23a86051ea35dbfb9f14e6511'] = 'Animiert abgerundete Ecken zum hier angegebenen Wert, wenn der Layer die Slider-Leinwand verlässt.'; // Animates rounded corners toward the value you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_493d9e9e60d44f987c62cd0201269cb5'] = 'Animiert die Layerbreite zum hier angegebenen Wert, wenn der Layer die Slider-Leinwand verlässt.'; // Animates the layer width toward the value you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_78ad1defbcb0f83255f363b25c4e9494'] = 'Animiert die Layerhöhe zum hier angegebenen Wert, wenn der Layer die Slider-Leinwand verlässt.'; // Animates the layer height toward the value you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_69f18587841a5200e32c92bd1309ae37'] = 'Textanimation'; // Text Animation
$_MODULE['<{layerslider}prestashop>_e92ac60744c22808ee11554229245b7c'] = 'Wählen Sie aus, wie Ihr Text aufgeteilt und animiert werden soll.'; // Select how your text should be split and animated.
