$_MODULE['<{layerslider}prestashop>_9b5a966beee53ac17871ab83ba520f5e'] = 'nach Zeilen von Rand nach Mitte'; // by lines edge to center
$_MODULE['<{layerslider}prestashop>_19c45324c9ca36d31215f056839a28c8'] = 'Einblenden'; // Shift In
$_MODULE['<{layerslider}prestashop>_02f41f49726759b91cf468825bdf41a2'] = 'Verzögert den Übergang jedes Textknotens relativ zueinander. Eine Sekunde entspricht 1000 Millisekunden.'; // Delays the transition of each text nodes relative to each other. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_3fff50b68e60ed555ff901b0fdfcd783'] = 'Verschiebt die Startposition von Textknoten von ihrer ursprünglichen auf der horizontalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. Die Werte \'links\' oder \'rechts\' positionieren Textknoten außerhalb des Staging-Bereichs, sodass sie von beiden Seiten in die Szene eintreten, wenn sie zu ihrem Zielort animiert werden. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Shifts the starting position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they enter the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_e1d2fdcc944aa0f2e839f171f044d659'] = 'Verschiebt die Startposition von Textknoten von ihrer ursprünglichen auf der vertikalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. Die Werte \'oben\' oder \'unten\' positionieren Textknoten außerhalb des Staging-Bereichs, sodass sie von beiden vertikalen Seiten in die Szene eintreten, wenn sie zu ihrem Zielort animiert werden. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Shifts the starting position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they enter the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_968c58d8f1922a6b84d393c59a64a49c'] = 'Die Übergangsdauer in Millisekunden der einzelnen Textfragmente. Eine Sekunde entspricht 1000 Millisekunden.'; // The transition length in milliseconds of the individual text fragments. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_ca6c773be9bea589e35cd5932032450e'] = 'Die Timing-Funktion der Animation. Mit dieser Funktion können Sie die Bewegung animierter Textfragmente manipulieren. Bitte klicken Sie auf den Link neben diesem Auswahlfeld, um easings.net für weitere Informationen und Echtzeit-Beispiele zu öffnen.'; // The timing function of the animation. With this function you can manipulate the movement of animated text fragments. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_218ff9f345230b14660e70e66162823f'] = 'Die Textfragmente während ihres Übergangs ausblenden.'; // Fade the text fragments during their transition.
$_MODULE['<{layerslider}prestashop>_87140560d2ebde43c1ee6bcbca46632b'] = 'StartBei'; // StartAt
$_MODULE['<{layerslider}prestashop>_5ca3eda902c20e71f2b8a9b37d6400e9'] = 'Öffnungsübergang beginnt'; // Opening Transition starts
$_MODULE['<{layerslider}prestashop>_fff3063495dd33cf3909fa4b1a9bc98d'] = 'Dreht Textfragmente im Uhrzeigersinn um die angegebene Gradzahl. Negative Werte sind für eine Drehung gegen den Uhrzeigersinn erlaubt. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Rotates text fragments clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_14f1aa4b97984dfcc375079b84f0eccc'] = 'Dreht Textfragmente entlang der X-Achse (horizontal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Rotates text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_871c9bdc8e8606162c54996b7f3e3d55'] = 'Dreht Textfragmente entlang der Y-Achse (vertikal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Rotates text fragments along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_fd776f8e6385f4f4e57c79701beb1f12'] = 'Skaliert Textfragmente entlang der X-Achse (horizontal) um den angegebenen Vektor. Verwenden Sie den Wert 1 für die Originalgröße. Der Wert 2 verdoppelt, während 0,5 Textfragmente im Vergleich zu ihrer Originalgröße verkleinert. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Scales text fragments along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_b95364eee0d39f1ff08c9511fd007c3b'] = 'Skaliert Textfragmente entlang der Y-Achse (vertikal) um den angegebenen Vektor. Verwenden Sie den Wert 1 für die Originalgröße. Der Wert 2 verdoppelt, während 0,5 Textfragmente im Vergleich zu ihrer Originalgröße verkleinert. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Scales text fragments along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_eec138a9b01bfa45053a9c2e34cc012a'] = 'Verzerrt Textfragmente entlang der X-Achse (horizontal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Skews text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_0e34f559e062c73fd9f20e88a6f2dff9'] = 'Verzerrt Textfragmente entlang der Y-Achse (vertikal) um die angegebene Gradzahl. Negative Werte sind für die umgekehrte Richtung erlaubt. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Skews text fragments along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_5160493a371ec5eaac86b380847e5df5'] = 'Ausblenden'; // Shift Out
$_MODULE['<{layerslider}prestashop>_ef90ee89ac37b9e0f7d58c40106d0489'] = 'Verschiebt die Endposition von Textknoten von ihrer ursprünglichen auf der horizontalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. Die Werte \'links\' oder \'rechts\' positionieren Textknoten außerhalb des Staging-Bereichs, sodass sie von beiden Seiten aus der Szene austreten, wenn sie zu ihrem Zielort animiert werden. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Shifts the ending position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they leave the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_a7dd960d399567a046b0614242132a75'] = 'Verschiebt die Endposition von Textknoten von ihrer ursprünglichen auf der vertikalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. Die Werte \'oben\' oder \'unten\' positionieren Textknoten außerhalb des Staging-Bereichs, sodass sie von beiden vertikalen Seiten aus der Szene austreten, wenn sie zu ihrem Zielort animiert werden. Durch die Auflistung mehrerer Werte, die durch ein |-Zeichen getrennt sind, verwendet der Slider unterschiedliche Übergangsvariationen für jeden Textknoten, indem er durch die angegebenen Werte wechselt.'; // Shifts the ending position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they leave the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_d3dd82ed2edaeee8b285d11df248cc2e'] = 'Verschiebt die Startposition des Layers von seiner ursprünglichen auf der horizontalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. Die Werte \'links\' oder \'rechts\' positionieren den Layer außerhalb des Staging-Bereichs, sodass er während des Übergangs die Szene von beiden Seiten verlassen und wieder betreten kann.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it can leave and re-enter the scene from either side during the transition.
$_MODULE['<{layerslider}prestashop>_ad02c3d94f8b3590b135be78e2f8e69f'] = 'Verschiebt die Startposition des Layers von seiner ursprünglichen auf der vertikalen Achse um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Höhe dieses Layers. Die Werte \'oben\' oder \'unten\' positionieren den Layer außerhalb des Staging-Bereichs, sodass er während des Übergangs die Szene von beiden vertikalen Seiten verlassen und wieder betreten kann.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it can leave and re-enter the scene from either vertical side during the transition.
$_MODULE['<{layerslider}prestashop>_7c1780aa74c2a852b5de424e51739b08'] = 'Die Dauer des Übergangs in Millisekunden. Eine Sekunde entspricht 1000 Millisekunden.'; // The length of the transition in milliseconds. A second is equal to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_c405823ea6eef48b12c76d719743050e'] = 'Die Timing-Funktion der Animation, um die Bewegung des Layers zu manipulieren. Klicken Sie auf den Link neben diesem Feld, um easings.net für Beispiele und weitere Informationen zu öffnen.'; // The timing function of the animation to manipualte the layer's movement. Click on the link next to this field to open easings.net for examples and more information
$_MODULE['<{layerslider}prestashop>_bad6a5dd8c28e6b14f8e986615e3dc98'] = 'Deckkraft'; // Opacity
$_MODULE['<{layerslider}prestashop>_52d096db2d41c73e647fc7b4afe9f4fb'] = 'Blendend den Layer ein/aus. Sie können Werte zwischen 1 und 0 verwenden, um den Layer vollständig undurchsichtig bzw. transparent zu machen. Zum Beispiel macht der Wert 0,5 den Layer halbtransparent.'; // Fades the layer. You can use values between 1 and 0 to set the layer fully opaque or transparent respectively. For example, the value 0.5 will make the layer semi-transparent.
$_MODULE['<{layerslider}prestashop>_e93f994f01c537c4e2f7d8528c3eb5e9'] = 'Anzahl'; // Count
$_MODULE['<{layerslider}prestashop>_dc9335e13408a714d8e29bf6e5b4af65'] = 'Die Anzahl der Wiederholungen des Schleifenübergangs. Die Zählung umfasst den umgekehrten Teil der Übergänge, wenn Sie die Yoyo-Funktion verwenden. Verwenden Sie den Wert -1, um unendlich zu wiederholen, oder null, um die Schleife zu deaktivieren.'; // The number of times repeating the Loop transition. The count includes the reverse part of the transitions when you use the Yoyo feature. Use the value -1 to repeat infinitely or zero to disable looping.
$_MODULE['<{layerslider}prestashop>_0f68101772bd5397ef8eb1b632798652'] = 'Warten'; // Wait
$_MODULE['<{layerslider}prestashop>_a2dd61cfcfc0bbdf8e5d0bacf03a4bfe'] = 'Wartezeit zwischen den Wiederholungen in Millisekunden. Eine Sekunde entspricht 1000 Millisekunden.'; // Waiting time between repeats in milliseconds. A second is 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_7eebb65ba3f2d0b0d5ca4135a1291800'] = 'Yoyo'; // Yoyo
$_MODULE['<{layerslider}prestashop>_d2157b3302d4ec2fb08023a69d4568fd'] = 'Aktivieren Sie diese Option, um einen umgekehrten Übergang zu ermöglichen, damit Sie nahtlos hin und her wechseln können.'; // Enable this option to allow reverse transition, so you can loop back and forth seamlessly.
$_MODULE['<{layerslider}prestashop>_0211cac74bd72aaae2f7886b1cbde16f'] = 'Verschiebt den Layer horizontal um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. '; // Moves the layer horizontally by the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer.
$_MODULE['<{layerslider}prestashop>_780daa5a10788add2c24feda0a7046c9'] = 'Verschiebt den Layer vertikal um die angegebene Anzahl von Pixeln. Verwenden Sie negative Werte für die entgegengesetzte Richtung. Prozentwerte beziehen sich auf die Breite dieses Layers. '; // Moves the layer vertically by the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer.
$_MODULE['<{layerslider}prestashop>_70f03c22e8756d36e8ebebf24fc83e68'] = 'Umkehr-<br>Dauer'; // Reverse<br>duration
$_MODULE['<{layerslider}prestashop>_f611f13e9d52fe21bddfa2b3c9c6e90a'] = 'Die Dauer des umgekehrten Übergangs in Millisekunden. Eine Sekunde entspricht 1000 Millisekunden.'; // The duration of the reverse transition in milliseconds. A second is equal to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_36883b3adac19e03ce6e8258a16fbd87'] = 'Umkehr-<br>Easing'; // Reverse<br>easing
$_MODULE['<{layerslider}prestashop>_0e95be22e52ba91b2a4eac69dea794c6'] = 'Die Timing-Funktion der umgekehrten Animation, um die Bewegung des Layers zu manipulieren. Klicken Sie auf den Link neben diesem Feld, um easings.net für Beispiele und weitere Informationen zu öffnen.'; // The timing function of the reverse animation to manipualte the layer's movement. Click on the link next to this field to open easings.net for examples and more information
$_MODULE['<{layerslider}prestashop>_18520e0c41ef4863b7c3d57b41e13dd2'] = 'Dreht den Layer im Uhrzeigersinn um die angegebene Gradzahl. Negative Werte sind für eine Drehung gegen den Uhrzeigersinn erlaubt.'; // Rotates the layer clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_178d558f0ec11adc7f14494caafecfa4'] = 'Die Hintergrundfarbe dieses Layers. Sie können Farbnamen, hexadezimale, RGB- oder RGBA-Werte sowie das Schlüsselwort \'transparent\' verwenden. Beispiel: #FFF'; // The background color of this layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_7ccb130b01ecf6f307e49d85d78101ae'] = 'Die Textfarbe dieses Textes. Sie können Farbnamen, hexadezimale, RGB- oder RGBA-Werte verwenden. Beispiel: #333'; // The text color of this text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_22b4e7bf3118d625243554505037c3d4'] = 'Abgerundete Ecken'; // Rounded corners
$_MODULE['<{layerslider}prestashop>_8baecbc8f47d34ba6f2c94c840039b5d'] = 'Wenn Sie abgerundete Ecken wünschen, können Sie hier deren Radius in Pixeln festlegen. Beispiel: 5px'; // If you want rounded corners, you can set here its radius in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_91b9f1c422bb9c80c97c1409c449b01a'] = 'Ändert die Perspektive von Layern im 3D-Raum.'; // Changes the perspective of layers in the 3D space.
$_MODULE['<{layerslider}prestashop>_7b57923badae7705a941c2bb5fdbc259'] = 'Immer im Vordergrund'; // Always on top
$_MODULE['<{layerslider}prestashop>_97309a236d6310d21531928e0f237909'] = 'Zeigen Sie diesen Layer beim Hover über allen anderen Layern an.'; // Show this layer above every other layer while hovering.
$_MODULE['<{layerslider}prestashop>_b437c451aa3282f75304078beaccd7f2'] = 'Parallax-Level'; // Parallax Level
$_MODULE['<{layerslider}prestashop>_6d88cda2a17e8c8ba371534044e4dcac'] = 'Legen Sie die Intensität des Parallax-Effekts fest. Verwenden Sie negative Werte, um Layer in die entgegengesetzte Richtung zu verschieben.'; // Set the intensity of the parallax effect. Use negative values to shift layers in the opposite direction.
$_MODULE['<{layerslider}prestashop>_e32aeb1f97bbc4b3734bceba06e62189'] = 'Wählen Sie, ob Sie 2D- oder 3D-Parallax-Layer möchten.'; // Choose if you want 2D or 3D parallax layers.
$_MODULE['<{layerslider}prestashop>_db7e7d3165d15f05c446c312cd7ce748'] = 'Von Folienoptionen erben'; // Inherit from Slide Options
$_MODULE['<{layerslider}prestashop>_65c19dcd436dba37e3f61abaa74fcb0a'] = 'Sie können den Parallax-Effekt entweder durch Scrollen der Seite oder durch Bewegen des Mauszeigers / Neigen Ihres Mobilgeräts auslösen.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device.
$_MODULE['<{layerslider}prestashop>_df4937d57d5546a1b7cad8aa01382a30'] = 'Wählen Sie, auf welchen Achsen sich Parallax-Layer bewegen sollen.'; // Choose on which axes parallax layers should move.
$_MODULE['<{layerslider}prestashop>_130c5b3473c57faa76e2a1c54e26f88e'] = 'Beide'; // Both
$_MODULE['<{layerslider}prestashop>_f8669b1c29bb1d386ed994a5fa3b2383'] = 'Bewegungsdauer'; // Move Duration
$_MODULE['<{layerslider}prestashop>_902394e5c2f298dc004991c64ea639e0'] = 'Steuert die Geschwindigkeit der Animation von Layern, wenn Sie Ihren Mauszeiger bewegen oder Ihr Mobilgerät neigen.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device.
$_MODULE['<{layerslider}prestashop>_e6c62193f078181acd6cc60c21353d08'] = 'Verlassensdauer'; // Leave Duration
$_MODULE['<{layerslider}prestashop>_387b79d99e6882187a0e3530f37a2f76'] = 'Steuert, wie schnell Parallax-Layer zu ihrer ursprünglichen Position zurückkehren, wenn Sie Ihren Mauszeiger außerhalb des Sliders bewegen. Dieser Wert ist in Millisekunden. Eine Sekunde entspricht 1000 Millisekunden.'; // Controls how quickly parallax layers revert to their original position when you move your mouse cursor outside of the slider. This value is in milliseconds. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_64a0612acd329567a634da43b59883cf'] = 'Erhöhen oder verringern Sie die Rotationsmenge des Layers im 3D-Raum, wenn Sie Ihren Mauszeiger bewegen oder auf einem mobilen Gerät neigen.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device.
$_MODULE['<{layerslider}prestashop>_fb86197f4f68b1e2d86783659e7585a3'] = 'Erhöhen oder verringern Sie die Bewegungsmenge des Layers, wenn Sie Ihren Mauszeiger bewegen oder auf einem mobilen Gerät neigen.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device.
$_MODULE['<{layerslider}prestashop>_7b62b4d0a7de4d976159fb96a6fa6411'] = 'Statischer Layer'; // Static layer
$_MODULE['<{layerslider}prestashop>_9ae2250c53514362ad6490c3431e5464'] = 'Sie können diesen Layer über mehrere Folien hinweg auf dem Slider halten. Wählen Sie einfach die Folie aus, auf der dieser Layer ausblenden soll. Alternativ können Sie diesen Layer global auf allen Folien machen, nachdem er eingeblendet wurde.'; // You can keep this layer on top of the slider across multiple slides. Just select the slide on which this layer should animate out. Alternatively, you can make this layer global on all slides after it transitioned in.
$_MODULE['<{layerslider}prestashop>_9c2690b8a4048048e2c037e4a03339b0'] = 'Deaktiviert (Standard)'; // Disabled (default)
$_MODULE['<{layerslider}prestashop>_1d7e5793a0150b3c05de1922cc8c16f5'] = 'Aktiviert (niemals ausblenden)'; // Enabled (never animate out)
$_MODULE['<{layerslider}prestashop>_2a36e79a98871dc76bf33a51af7e3715'] = 'Keyframe für Abspielen durch Scrollen'; // Play By Scroll Keyframe
$_MODULE['<{layerslider}prestashop>_8e898860158d07998968bfd485788069'] = 'Ein "Abspielen durch Scrollen"-Slider wird pausieren, wenn dieser Layer seinen Öffnungsübergang beendet hat.'; // A Play by Scroll slider will pause when this layer finished its opening transition.
$_MODULE['<{layerslider}prestashop>_627b4c0e8a9b46747497d4bae491a6c2'] = 'Wenn Sie Ihren Layer verlinken möchten, geben Sie hier die URL ein. Sie können ein Rautezeichen gefolgt von einer Zahl verwenden, um diesen Layer mit einer anderen Folie zu verknüpfen. Beispiel: #3 - dies wechselt zur dritten Folie.'; // If you want to link your layer, type here the URL. You can use a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_a33a3e8542755c06996a81a78878b66b'] = 'URL-Ziel'; // URL target
$_MODULE['<{layerslider}prestashop>_ba333933886b07c9384523873559a3fd'] = 'Benutzerdefinierte Attribute'; // Custom Attributes
$_MODULE['<{layerslider}prestashop>_a016d8e10948cfc95215918d4372d8f9'] = 'Ihre Liste benutzerdefinierter Attribute. Verwenden Sie diese Funktion, wenn Ihre Bedürfnisse nicht durch die oben genannten allgemeinen Attribute abgedeckt sind oder Sie diese überschreiben möchten. Sie können sowohl data-*- als auch reguläre Attributnamen verwenden. Leere Attribute (ohne Wert) sind ebenfalls erlaubt. Um beispielsweise eine FancyBox-Galerie zu erstellen, können Sie "data-fancybox-group" und "gallery1" für den Attributnamen bzw. -wert eingeben.'; // Your list of custom attributes. Use this feature if your needs are not covered by the common attributes above or you want to override them. You can use data-* as well as regular attribute names. Empty attributes (without value) are also allowed. For example, to make a FancyBox gallery, you may enter "data-fancybox-group" and "gallery1" for the attribute name and value, respectively.
$_MODULE['<{layerslider}prestashop>_edac8da7d60b7624d4b131bc47a5eb3b'] = 'Sie können die Breite Ihres Layers festlegen. Sie können Pixel, Prozent oder den Standardwert \'auto\' verwenden. Beispiele: 100px, 50% oder auto.'; // You can set the width of your layer. You can use pixels, percentage, or the default value 'auto'. Examples: 100px, 50% or auto.
$_MODULE['<{layerslider}prestashop>_c6272de402f4e075758f7d27f108d6c1'] = 'Sie können die Höhe Ihres Layers festlegen. Sie können Pixel, Prozent oder den Standardwert \'auto\' verwenden. Beispiele: 100px, 50% oder auto'; // You can set the height of your layer. You can use pixels, percentage, or the default value 'auto'. Examples: 100px, 50% or auto
$_MODULE['<{layerslider}prestashop>_a4ffdcf0dc1f31b9acaf295d75b51d00'] = 'Oben'; // Top
$_MODULE['<{layerslider}prestashop>_4ce53ede45d38aa6228b7a2e4a9a2d6f'] = 'Die Position des Layers von oben auf der Folie. Sie können Pixel und Prozent verwenden. Beispiele: 100px oder 50%. Sie können Ihre Layer in der Vorschau oben mit Drag & Drop verschieben oder hier die genauen Werte festlegen.'; // The layer position from the top of the slide. You can use pixels and percentage. Examples: 100px or 50%. You can move your layers in the preview above with a drag n' drop, or set the exact values here.
$_MODULE['<{layerslider}prestashop>_945d5e233cf7d6240f6b783b36a374ff'] = 'Links'; // Left
$_MODULE['<{layerslider}prestashop>_38ab4523d162374efdee06dcaa89d7dd'] = 'Die Position des Layers von der linken Seite der Folie. Sie können Pixel und Prozent verwenden. Beispiele: 100px oder 50%. Sie können Ihre Layer in der Vorschau oben mit Drag & Drop verschieben oder hier die genauen Werte festlegen.'; // The layer position from the left side of the slide. You can use pixels and percentage. Examples: 100px or 50%. You can move your layers in the preview above with a drag n' drop, or set the exact values here.
