$_MODULE['<{layerslider}prestashop>_935d167268be2e114d55069d55e1a408'] = 'Oblique ist eine automatisch generierte kursive Version Ihrer gewählten Schriftart und kann eine Schrägstellung erzwingen, auch wenn keine kursive Schriftvariante verfügbar ist. Sie sollten jedoch die reguläre kursive Option verwenden, wann immer dies möglich ist. Bitte überprüfen Sie, ob Sie kursive Schriftvarianten laden, wenn Sie Google Fonts verwenden.'; // Oblique is an auto-generated italic version of your chosen font and can force slating even if there is no italic font variant available. However, you should use the regular italic option whenever is possible. Please double check to load italic font variants when using Google Fonts.
$_MODULE['<{layerslider}prestashop>_1d874710ccdcd46b95397049d2e7500c'] = 'Kursiv'; // Italic
