$_MODULE['<{layerslider}prestashop>_6d40b0cbf0593b752ece63f7a9928eef'] = 'Steuert den Abstand zwischen den einzelnen Zeichen. Nützlich, um die Buchstabendichte in einer Zeile oder einem Textblock zu ändern. Negative Werte und Dezimalzahlen können verwendet werden.'; // Controls the amount of space between each character. Useful the change letter density in a line or block of text. Negative values and decimals can be used.
$_MODULE['<{layerslider}prestashop>_c22b28c5c38d219b521e476691bd7158'] = 'Textausrichtung'; // Text align
$_MODULE['<{layerslider}prestashop>_6c982f951a9fa0736c853e9353ff1553'] = 'Initial (Sprachstandard)'; // Initial (Language default)
$_MODULE['<{layerslider}prestashop>_4f1f6016fc9f3f2353c0cc7c67b292bd'] = 'Zentriert'; // Center
$_MODULE['<{layerslider}prestashop>_4b425d212a2e7b36c38703bfdcd57823'] = 'Blocksatz'; // Justify
