$_MODULE['<{layerslider}prestashop>_e0bc0f8bfc07dfaa60de8a19a075ecaf'] = 'Min. mobile Schriftgröße'; // Min. mobile font size
$_MODULE['<{layerslider}prestashop>_56cac8df2a819eb309f656bec767e641'] = 'Die minimale Schriftgröße in einem responsiven Slider auf mobilen Geräten. Diese Option ermöglicht es Ihnen zu verhindern, dass Ihre Textebenen auf kleineren Bildschirmen zu klein werden.'; // The minimum font size in a responsive slider on mobile devices. This option allows you to prevent your texts layers becoming too small on smaller screens.
$_MODULE['<{layerslider}prestashop>_ee0b6a872572cc985f1d5d20a5901ffb'] = 'Wenn Sie abgerundete Ecken wünschen, können Sie deren Radius hier festlegen. Beispiel: 5px'; // If you want rounded corners, you can set its radius here. Example: 5px
$_MODULE['<{layerslider}prestashop>_856ba67470300f8246b140de9a27555d'] = 'Benutzerdefinierte Stile'; // Custom styles
$_MODULE['<{layerslider}prestashop>_7e045337d227fc13f0b7efdadf341169'] = 'Wenn Sie andere Stileinstellungen als die oben genannten festlegen möchten, können Sie hier beliebigen CSS-Code verwenden. Bitte stellen Sie sicher, dass Sie eine gültige Syntax schreiben.'; // If you want to set style settings other than above, you can use here any CSS codes. Please make sure to write valid markup.
$_MODULE['<{layerslider}prestashop>_3dbe275d40b3a2b680bdfa25242cc8fe'] = 'Der Drehwinkel, zu dem dieser Layer animiert wird, wenn er in die Slider-Leinwand eintritt. Negative Werte sind für eine Drehung gegen den Uhrzeigersinn erlaubt.'; // The rotation angle where this layer animates toward when entering into the slider canvas. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_fe75b60943091f007ae820a3188868a2'] = 'Der Drehwinkel auf der horizontalen Achse, zu dem er animiert wird, wenn er in die Slider-Leinwand eintritt. Negative Werte sind für die umgekehrte Richtung erlaubt.'; // The rotation angle on the horizontal axis where this animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_0c6a5ad5f832c1f79c4b4d62fee16e26'] = 'Der Drehwinkel auf der vertikalen Achse, zu dem dieser Layer animiert wird, wenn er in die Slider-Leinwand eintritt. Negative Werte sind für die umgekehrte Richtung erlaubt.'; // The rotation angle on the vertical axis where this layer animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_6af83f149c018cdec1dba351c619b7ca'] = 'Die horizontale Skalierung des Layers, zu der dieser Layer animiert wird, wenn er in die Slider-Leinwand eintritt.'; // The layer horizontal scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_28d8b2ec189dc2eb778a851265cf4f26'] = 'Die vertikale Skalierung des Layers, zu der dieser Layer animiert wird, wenn er in die Slider-Leinwand eintritt.'; // The layer vertical scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_63d48e08093f6964b3cdc6d33740663e'] = 'Der horizontale Neigungswinkel des Layers, zu dem dieser Layer animiert wird, wenn er in die Slider-Leinwand eintritt.'; // The layer horizontal skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_e4b23d4080824b973029720a307cbae6'] = 'Der vertikale Neigungswinkel des Layers, zu dem dieser Layer animiert wird, wenn er in die Slider-Leinwand eintritt.'; // The layer vertical skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_45f908bb74a7835d23630c7d51031fed'] = 'Positionen berechnen von'; // Calculate positions from
$_MODULE['<{layerslider}prestashop>_639b76980c25ea95700d2c2e96833964'] = 'Legt den Ursprung der Layer-Position fest, von dem aus die Werte für oben und links berechnet werden. Der Standard ist die obere linke Ecke der Slider-Leinwand. Bei einem Slider mit voller Breite und voller Größe wird Ihr Inhalt basierend auf der Bildschirmgröße zentriert, um die bestmögliche Passform zu erzielen. Durch Auswahl der Option "Seiten des Bildschirms" in diesen Szenarien können Sie Layern erlauben, den zentrierten inneren Bereich zu verlassen und an den Seiten des Bildschirms zu haften.'; // Sets the layer position origin from which top and left values are calculated. The default is the upper left corner of the slider canvas. In a full width and full size slider, your content is centered based on the screen size to achieve the best possible fit. By selecting the "sides of the screen" option in those scenarios, you can allow layers to escape the centered inner area and stick to the sides of the screen.
$_MODULE['<{layerslider}prestashop>_b16710c8d62abca1ccda544c63bea7e8'] = 'Seiten des Sliders'; // sides of the slider
$_MODULE['<{layerslider}prestashop>_ab761fc53dc83dca5a36b9a25bf548bf'] = 'Seiten des Bildschirms'; // sides of the screen
$_MODULE['<{layerslider}prestashop>_51400b417ad07f539ecfd9469027a5b6'] = 'Stapelreihenfolge'; // Stacking order
$_MODULE['<{layerslider}prestashop>_4c26a68fa7463987e86f61733caf8491'] = 'Diese Option steuert die vertikale Stapelreihenfolge von sich überlappenden Layern. In CSS wird dies üblicherweise als z-Index bezeichnet. Elemente mit einem höheren Wert werden vor Elementen mit einem niedrigeren Wert gestapelt und verdecken diese effektiv. Standardmäßig wird dieser Wert automatisch basierend auf der Reihenfolge Ihrer Layer berechnet, daher kann eine einfache Neuanordnung Überlappungsprobleme beheben. Verwenden Sie diese Option nur, wenn Sie in besonderen Fällen wie der Verwendung statischer Layer Ihren eigenen Wert manuell festlegen möchten.<br><br>Auf jeder Folie beginnt die Stapelreihenfolge bei 100. Die Angabe einer Zahl unter 100 platziert den Layer hinter allen anderen Layern auf allen Folien. Die Angabe einer viel größeren Zahl, zum Beispiel 500, sorgt dafür, dass der Layer über allem anderen liegt.'; // This option controls the vertical stacking order of layers that overlap. In CSS, it's commonly called as z-index. Elements with a higher value are stacked in front of elements with a lower one, effectively covering them. By default, this value is calculated automatically based on the order of your layers, thus simply re-ordering them can fix overlap issues. Use this option only if you want to set your own value manually in special cases like using static layers.<br><br>On each slide, the stacking order starts counting from 100. Providing a number less than 100 will put the layer behind every other layer on all slides. Specifying a much greater number, for example 500, will make the layer to be on top of everything else.
$_MODULE['<{layerslider}prestashop>_0c301043ef92f5854d711e54f96a86c5'] = 'Mischmodus'; // Blend mode
$_MODULE['<{layerslider}prestashop>_df5c4d0c2cd9156afa20fa59c572acde'] = 'Wählen Sie, wie Layer und der Folienhintergrund ineinander übergehen sollen. Mischmodi sind eine einfache Möglichkeit, auffällige Effekte hinzuzufügen und gehören zu den am häufigsten verwendeten Funktionen im Grafik- und Druckdesign.'; // Choose how layers and the slide background should blend into each other. Blend modes are an easy way to add eye-catching effects and is one of the most frequently used features in graphic and print design.
$_MODULE['<{layerslider}prestashop>_b718adec73e04ce3ec720dd11a06a308'] = 'ID'; // ID
$_MODULE['<{layerslider}prestashop>_ca79528715d6c07cb429e8189105cbb4'] = 'Sie können dem HTML-Element dieses Layers ein ID-Attribut zuweisen, um damit in Ihrem benutzerdefinierten CSS- oder Javascript-Code zu arbeiten.'; // You can apply an ID attribute on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_e9878b4854d29907146149f695cb1cfb'] = 'Klassen'; // Classes
$_MODULE['<{layerslider}prestashop>_c666f7b19a598af3cadb8c9cb07c4bcd'] = 'Sie können dem HTML-Element dieses Layers Klassen zuweisen, um damit in Ihrem benutzerdefinierten CSS- oder Javascript-Code zu arbeiten.'; // You can apply classes on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_3ace045d5becea8953aabde365c5c8d8'] = 'Sie können diesem Layer einen Titel hinzufügen, der als Tooltip angezeigt wird, wenn jemand seinen Mauszeiger über den Layer hält.'; // You can add a title to this layer which will display as a tooltip if someone holds his mouse cursor over the layer.
$_MODULE['<{layerslider}prestashop>_f2364c335fe8ae15c8d64b2744db0f40'] = 'Benennen oder beschreiben Sie Ihren Bild-Layer, damit Suchmaschinen und VoiceOver-Software ihn richtig identifizieren können.'; // Name or describe your image layer, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_eba991d56b1be0b940d722211bab87bc'] = 'Rel'; // Rel
$_MODULE['<{layerslider}prestashop>_b987cf5b1aa6af2a92b97f69d65c29df'] = 'Plugins und Suchmaschinen können dieses Attribut verwenden, um mehr Informationen über die Rolle und das Verhalten eines Links zu erhalten.'; // Plugins and search engines may use this attribute to get more information about the role and behavior of a link.
$_MODULE['<{layerslider}prestashop>_5d083603a18046659c2b4b23af7948cc'] = 'Erweiterte Option'; // Advanced option
$_MODULE['<{layerslider}prestashop>_31fde7b05ac8952dacf4af8a704074ec'] = 'Vorschau'; // Preview
$_MODULE['<{layerslider}prestashop>_a67f2c9d056f29b94521c17b838b9756'] = 'Kacheln'; // Tiles
$_MODULE['<{layerslider}prestashop>_530f488f7a9800411efc6926ab189708'] = 'Zeilen'; // Rows
$_MODULE['<{layerslider}prestashop>_35b93b52adc0893d6f4b32752660535f'] = '<i>zahl</i> oder <i>min,max</i> Wenn Sie einen Wert größer als 1 angeben, wird Creative Slider Ihre Folie in Kacheln schneiden. Sie können hier angeben, wie viele Zeilen Ihr Übergang haben soll. Wenn Sie zwei durch ein Komma getrennte Zahlen angeben, wird Creative Slider dies als Bereich verwenden und eine Zufallszahl zwischen Ihren Werten auswählen.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many rows of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_d27561f45c58f407b3fe76b63b1ec28a'] = 'Spalten'; // Cols
$_MODULE['<{layerslider}prestashop>_a122bf49cbf8c9cf02971a495e81ed16'] = '<i>zahl</i> oder <i>min,max</i> Wenn Sie einen Wert größer als 1 angeben, wird Creative Slider Ihre Folie in Kacheln schneiden. Sie können hier angeben, wie viele Spalten Ihr Übergang haben soll. Wenn Sie zwei durch ein Komma getrennte Zahlen angeben, wird Creative Slider dies als Bereich verwenden und eine Zufallszahl zwischen Ihren Werten auswählen.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many columns of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_8f497c1a3d15af9e0c215019f26b887d'] = 'Verzögerung'; // Delay
$_MODULE['<{layerslider}prestashop>_d4f0208d1a34d7a381fc8abec990105b'] = 'Sie können eine Verzögerung zwischen den Kacheln anwenden und deren Animation relativ zueinander verschieben.'; // You can apply a delay between the tiles and postpone their animation relative to each other.
$_MODULE['<{layerslider}prestashop>_3ff39d3acb327553070a64ef0cb321d5'] = 'Sequenz'; // Sequence
$_MODULE['<{layerslider}prestashop>_434cd8b268e79b39af562cc6329d56fb'] = 'Sie können hier die Animationsreihenfolge der Kacheln steuern.'; // You can control the animation order of the tiles here.
$_MODULE['<{layerslider}prestashop>_67d2f6740a8eaebf4d5c6f79be8da481'] = 'Vorwärts'; // Forward
$_MODULE['<{layerslider}prestashop>_67f115c1fddc4ce1aeb1c754001585bc'] = 'Rückwärts'; // Reverse
$_MODULE['<{layerslider}prestashop>_13db785ec723ba5b44f1a1311edc9332'] = 'Spalte-vorwärts'; // Col-forward
$_MODULE['<{layerslider}prestashop>_3898dd1cf4144fda9dfac68e6c3b7c41'] = 'Spalte-rückwärts'; // Col-reverse
