$_MODULE['<{layerslider}prestashop>_a9aad76491b11de0946f522d395fddc6'] = 'Jedes Textfragment wird vom gemeinsamen ganzen Wort zu den hier angegebenen Optionen animiert.'; // Each text fragment will animate from the joint whole word to the options you specify here.
$_MODULE['<{layerslider}prestashop>_f9e9df31a5676a4d5f1bcb56ca7d6728'] = 'Die folgenden Optionen sind die Endwerte, zu denen dieser Layer animiert wird, wenn er die Slider-Leinwand verlässt.'; // The following options will be the end values where this layer animates toward when it leaves the slider canvas.
