$_MODULE['<{layerslider}prestashop>_04099750838e0b2fc6c9d68c5dc47b42'] = 'Seien Sie beruhigt, dass Ihre Slider-Bearbeitungen immer sicher sind und Sie unerwünschte Änderungen oder fehlerhafte Speicherungen jederzeit rückgängig machen können. Diese Funktion dient nicht nur als Backup-Lösung, sondern als komplettes Versionskontrollsystem, mit dem Sie die vorgenommenen Änderungen visuell vergleichen können.'; // Have a peace of mind knowing that your slider edits are always safe and you can revert back unwanted changes or faulty saves at any time. This feature serves not just as a backup solution, but a complete version control system where you can visually compare the changes you have made along the way.
$_MODULE['<{layerslider}prestashop>_3a06c5ff9c120c2e7e49750f76c3b0c9'] = 'Revisions-Einstellungen anpassen'; // Customize Revisions Preferences
