$_MODULE['<{layerslider}prestashop>_026a0484241f4c579c5e3570b3e1b787'] = 'Begrenzen Sie die Gesamtzahl der Revisionen pro Slider auf %s.'; // Limit the total number of revisions per slider to %s.
$_MODULE['<{layerslider}prestashop>_85e5569165918988076ed20f567709ab'] = 'Warten Sie mindestens %s Minuten zwischen den Bearbeitungen, bevor Sie eine neue Revision hinzufügen.'; // Wait at least %s minutes between edits before adding a new revision.
$_MODULE['<{layerslider}prestashop>_a79dc794e7af45729dfba74a532f0ad6'] = 'Slider-Revisionen speichern auch die Rückgängig-/Wiederherstellen-Steuerelemente. Es gibt keinen Grund, sehr häufige Speicherungen zu verwenden, da Sie die Änderungen dazwischen rückgängig machen können.'; // Slider Revisions also stores the undo/redo controls. There is no reason using very frequent saves since you will be able to undo the changes in-between.
