$_MODULE['<{layerslider}prestashop>_dae53216ad3909742ad508599f4f524c'] = 'Spezialeffekte sind wie normale Folienübergänge und funktionieren auf die gleiche Weise. Sie können sie auf jeder Folie einzeln einstellen. Das Mischen mit anderen Übergängen auf anderen Folien ist absolut in Ordnung. Sie können sie auch auf alle Ihre Folien gleichzeitig anwenden, indem Sie oben auf die Schaltfläche "Auf andere anwenden" klicken. Bei 3D-Spezialeffekten kann die Auswahl zusätzlicher 2D-Übergänge die Abwärtskompatibilität für ältere Browser gewährleisten.'; // Special effects are like regular slide transitions and they work in the same way. You can set them on each slide individually. Mixing them with other transitions on other slides is perfectly fine. You can also apply them on all of your slides at once by pressing the "Apply to others" button above. In case of 3D special effects, selecting additional 2D transitions can ensure backward compatibility for older browsers.
$_MODULE['<{layerslider}prestashop>_b8855caaf641a9f8cd794b263fd3187f'] = 'Origami-Übergang'; // Origami transition
$_MODULE['<{layerslider}prestashop>_120a5b58df4cf329020874fee6e1a01c'] = 'Teilen Sie Ihre wunderschönen Fotos auf wirklich inspirierende Weise mit der Welt oder Ihren Lieben und erstellen Sie mit Origami Slider mit atemberaubenden Effekten.'; // Share your gorgeous photos with the world or your loved ones in a truly inspirational way and create sliders with stunning effects with Origami.
$_MODULE['<{layerslider}prestashop>_2b0cda1ac8369a2372e2de48907dabc4'] = 'Origami ist eine Form des 3D-Übergangs und funktioniert auf die gleiche Weise wie normale Folienübergänge. Außer im Internet Explorer funktioniert Origami in allen modernen Browsern (einschließlich Edge).'; // Origami is a form of 3D transition and it works in the same way as regular slide transitions do. Besides Internet Explorer, Origami works in all the modern browsers (including Edge).
$_MODULE['<{layerslider}prestashop>_d8051901953ab9ec06e0bd5e929da146'] = 'Auf dieser Folie verwenden'; // Use it on this slide
