$_MODULE['<{layerslider}prestashop>_5ed18aa2ff3d637f7b743a20c913047b'] = 'Hier können Sie Ihre zuvor exportierten Slider hochladen. Um sie auf Ihre Website zu importieren, müssen Sie nur die entsprechende Exportdatei (Dateien mit den Erweiterungen .zip oder .json) auswählen und dann auf die Schaltfläche "Slider importieren" klicken.'; // Here you can upload your previously exported sliders. To import them to your site, you just need to choose and select the appropriate export file (files with .zip or .json extensions), then press the Import Sliders button.
$_MODULE['<{layerslider}prestashop>_d69de1175ad3d34048bfd72f8c2728ea'] = 'Suchen Sie nach dem importierbaren Demo-Inhalt? Schauen Sie sich den %sVorlagen-Store%s an.'; // Looking for the importable demo content? Check out the %sTemplate Store%s.
$_MODULE['<{layerslider}prestashop>_cc0da7a91d632e541ca11db8e8e77c18'] = 'Hinweis: Um aus veralteten Versionen (vor v3.0.0) zu importieren, müssen Sie eine neue Datei erstellen und den Exportcode darin einfügen. Die Datei muss die Erweiterung .json haben, dann können Sie sie hochladen.'; // Notice: In order to import from outdated versions (pre-v3.0.0), you need to create a new file and paste the export code into it. The file needs to have a .json extension, then you will be able to upload it.
$_MODULE['<{layerslider}prestashop>_d1673e2c8908f8939c5d0ba949ebc80b'] = 'Slider importieren'; // Import Sliders
$_MODULE['<{layerslider}prestashop>_00a38f6db60b94e13225141261806f19'] = 'Für den ausgewählten Slider sind noch keine Revisionen verfügbar. Revisionen werden im Laufe der Zeit hinzugefügt, wenn Sie neue Änderungen an Ihren Slidern vornehmen. Überprüfen Sie die %sRevisions-Einstellungen%s und stellen Sie sicher, dass Revisionen aktiviert sind.'; // There are no revisions available for the selected slider yet. Revisions will be added over time when you make new changes to your sliders. Check %sRevisions Preferences%s and make sure that Revisions is enabled.
