$_MODULE['<{layerslider}prestashop>_910ce384627367e87e43f3c12bf196ce'] = 'Vergessen Sie nicht, diese Option später zu deaktivieren, wenn sie nicht hilft oder wenn Sie unerwartete Probleme haben. Dies betrifft Ihre gesamte Website, nicht nur Creative Slider.'; // Do not forget to disable this option later on if it does not help, or if you experience unexpected issues. This includes your entire site, not just Creative Slider.
$_MODULE['<{layerslider}prestashop>_7d2879c37f82368b712923d1dc1acd58'] = 'Wird importiert, bitte warten...'; // Importing, please wait...
